  W("around", "/əˈraʊnd/", "preposition", "навколо", "There are trees around the lake.", "Навколо озера є дерева."),
  W("above", "/əˈbʌv/", "preposition", "над, вище", "There is a lamp above the table.", "Над столом є лампа."),
  W("in the middle of", "/ɪn ðə ˈmɪdl əv/", "phrase", "посередині", "There is a fountain in the middle of the park.", "Посеред парку є фонтан."),
